(function(root){
 'use strict';
 // All volume references are litres. The simulation stores cloud volume in game mL.
 const CONFIG=Object.freeze({creditsPerLitre:1000,maxBonus:.25,puffReferenceLitres:.010,durationReferenceSeconds:3,efficiencyReferenceLitresPerUnit:.002,energyReferenceLitresPerWh:1,throughputReference:.004,throughputMaxBonus:.5,minCleanSeconds:.75,minCleanLitres:.002,smokeStrength:2});
 const positive=n=>Number.isFinite(n)&&n>=0?n:0;
 const litres=mL=>positive(mL)/1000;
 const bonus=(value,reference)=>1+CONFIG.maxBonus*value/(value+reference);
 function qualifying(p){return !!p&&p.reason!=='interrupted'&&p.duration>=CONFIG.minCleanSeconds-1e-8&&litres(p.vapor)>=CONFIG.minCleanLitres-1e-10&&p.smoke<=1e-8&&!(p.hot>1e-8)&&!(p.dry>1e-8);}
 function track(round,p){if(p.reason==='interrupted')return;round.largestEligible=Math.max(round.largestEligible||0,p.vapor);if(qualifying(p))round.longestClean=Math.max(round.longestClean||0,p.duration);}
 function performance(r){const session=r.timingKnown===true?positive(r.elapsed):null,firing=r.firingKnown===true?positive(r.firingTime):null;return {session,firing,throughput:session>0?litres(r.vapor)/session:null,liquidRate:session>0&&r.liquidKnown===true?positive(r.liquidUsed)/session:null,averagePower:firing>0&&r.energyKnown===true?positive(r.energyUsed)*3600/firing:null};}
 function calculate(round){const clean=litres(round.vapor),smoke=litres(round.smoke),largest=litres(round.largestEligible),duration=positive(round.longestClean),used=positive(round.liquidUsed),largestKnown=round.largestKnown===true,durationKnown=round.durationKnown===true,liquidKnown=round.liquidKnown===true;
  const efficiency=liquidKnown&&used>0?clean/used:null,sizeBonus=largestKnown?bonus(largest,CONFIG.puffReferenceLitres):1,durationBonus=durationKnown?bonus(duration,CONFIG.durationReferenceSeconds):1,efficiencyBonus=efficiency!==null?1+(bonus(efficiency,CONFIG.efficiencyReferenceLitresPerUnit)-1)*(round.throughputModel?.4:1):1;
  const base=clean*CONFIG.creditsPerLitre,smokePenalty=clean>0?1/(1+CONFIG.smokeStrength*smoke/clean):1,energyUsed=positive(round.energyUsed),energyKnown=round.energyKnown===true,energyEfficiency=energyKnown&&energyUsed>0?clean/energyUsed:null,energyBonus=energyEfficiency===null?1:1+(bonus(energyEfficiency,CONFIG.energyReferenceLitresPerWh)-1)*(round.throughputModel?.4:1),perf=performance(round),maturity=Math.min(1,Math.max(0,((perf.firing||0)-1)/3))*Math.min(1,Math.max(0,(clean-.005)/.005)),throughputBonus=round.throughputModel&&perf.throughput!==null?1+CONFIG.throughputMaxBonus*perf.throughput/(perf.throughput+CONFIG.throughputReference)*maturity:1,commitment=round.throughputModel?.05+.95*Math.min(1,Math.max(round.sessionEnergy>0?energyUsed/round.sessionEnergy:0,round.sessionLiquid>0?used/round.sessionLiquid:0)/.75)**2:1,beforeSmoke=base*commitment*sizeBonus*durationBonus*efficiencyBonus*energyBonus*throughputBonus,credits=clean>0?beforeSmoke*smokePenalty:0;
  return {version:round.throughputModel?3:2,performance:perf,commitment,throughputBonus,energyUsed,energyKnown,energyEfficiency,energyBonus,credits,base,beforeSmoke,smokeReduction:beforeSmoke-credits,sizeBonus,durationBonus,efficiencyBonus,smokePenalty,cleanLitres:clean,smokeLitres:smoke,largestLitres:largest,longestSeconds:duration,liquidUsed:used,efficiency,largestKnown,durationKnown,liquidKnown,config:{...CONFIG}};
 }
 function report(saved,round){if(![1,2,3].includes(saved?.version))return calculate(round);const out=calculate(round);for(const key of Object.keys(out)){if(typeof out[key]==='number'&&Number.isFinite(saved[key])&&saved[key]>=0)out[key]=saved[key];else if(typeof out[key]==='boolean')out[key]=saved[key]===true;}out.version=saved.version;out.throughputBonus=saved.version<3?1:positive(saved.throughputBonus)||1;out.performance=performance(round);if(saved.version===1){out.energyKnown=false;out.energyBonus=1;out.energyEfficiency=null;}else out.energyEfficiency=Number.isFinite(saved.energyEfficiency)?saved.energyEfficiency:null;out.efficiency=Number.isFinite(saved.efficiency)&&saved.efficiency>=0?saved.efficiency:null;for(const key in out.config)if(Number.isFinite(saved.config?.[key])&&saved.config[key]>0)out.config[key]=saved.config[key];return out;}
 const api={performance,CONFIG,litres,bonus,qualifying,track,calculate,report};root.CloudEarnings=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
